use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder\TemplateVersionVersionAttributeHolder;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionVersionVO;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class TemplateVersionAttributes
{
  use TemplateVersionUidAttributeHolder;
  use TemplateVersionTemplateAttributeHolder;
  use TemplateVersionSubjectAttributeHolder;
  use TemplateVersionContentHtmlAttributeHolder;
  use TemplateVersionContentTextAttributeHolder;
  use TemplateVersionVersionAttributeHolder;

  private const array UNSETS = [
    'uid' => 'unsetUid',
    'template' => 'unsetTemplate',
    'subject' => 'unsetSubject',
    'contentHtml' => 'unsetContentHtml',
    'contentText' => 'unsetContentText',
    'version' => 'unsetVersion',
  ];

  public function build(): TemplateVersion
  {
    $errors = new ConstraintFailList();
        $uid = TemplateVersionUidVO::tryFrom($this->uid, $errors);
        $template = TemplateVersionTemplateVO::tryFrom($this->template, $errors);
        $subject = TemplateVersionSubjectVO::tryFrom($this->subject, $errors);
        $contentHtml = TemplateVersionContentHtmlVO::tryFrom($this->contentHtml, $errors);
        $contentText = TemplateVersionContentTextVO::tryFrom($this->contentText, $errors);
        $version = TemplateVersionVersionVO::tryFrom($this->version, $errors);
    if( $errors->hasErrors() ) {
      throw $errors->asConstraintException();
    }
        \assert($uid !== null);        \assert($template !== null);        \assert($contentHtml !== null);    return new TemplateVersion(
      uid: $uid,
      template: $template,
      subject: $subject,
      contentHtml: $contentHtml,
      contentText: $contentText,
      version: $version,
    );
  }
  public function withAssertedRules(): TemplateVersionAttributes
  {
    $value = new TemplateVersionAttributes();
    $errorsList = new ConstraintFailList();
    $this->withAssertedUidRules($value, $errorsList);
    $this->withAssertedTemplateRules($value, $errorsList);
    $this->withAssertedSubjectRules($value, $errorsList);
    $this->withAssertedContentHtmlRules($value, $errorsList);
    $this->withAssertedContentTextRules($value, $errorsList);
    $this->withAssertedVersionRules($value, $errorsList);
    if ($errorsList->hasErrors()) {
      throw $errorsList->asConstraintException();
    }
    return $value;
  }
  public function unset(string $field): void
  {
    if (isset(self::UNSETS[$field])) {
      call_user_func([$this, self::UNSETS[$field]]);
    }
  }
  public function withDefaults(): TemplateVersionAttributes
  {
    $this->withDefaultUid();
    $this->withDefaultTemplate();
    $this->withDefaultSubject();
    $this->withDefaultContentHtml();
    $this->withDefaultContentText();
    $this->withDefaultVersion();
    return $this;
  }
}
